import tw.rex.link.*;import org.json.*;import java.nio.file.*;import java.util.*;
public class Logic100Test {
 static int count=0;static void ok(boolean b,String label){if(!b)throw new AssertionError(label);count++;System.out.println("PASS "+label);}
 static Set<String> topics=new HashSet<String>(Arrays.asList("logic"));
 static JSONObject config(int grade,JSONArray levels)throws Exception{return new JSONObject().put("grade",grade).put("subject",5).put("seconds",10).put("limit",0).put("topics",new JSONArray().put("logic")).put("logicLevels",levels).put("custom",new JSONArray());}
 public static void main(String[] args)throws Exception{
 JSONArray bank=new JSONArray(new String(Files.readAllBytes(Paths.get("tv-learning/assets/questions.json")),"UTF-8"));String[] codes={"easy","starter","intermediate","advanced"};int total=0;HashSet<Integer> numbers=new HashSet<Integer>();for(int i=0;i<bank.length();i++){JSONObject q=bank.getJSONObject(i);if(!q.optString("topic").equals("logic"))continue;total++;ok(q.getJSONArray("options").length()==3&&q.getJSONArray("options").toString().contains(q.getString("answer")),"question "+q.getString("id")+" has three choices and an answer");ok(!q.getString("explanation").isEmpty(),"question "+q.getString("id")+" includes explanation");numbers.add(q.getInt("logicNumber"));}ok(total==100&&numbers.size()==100&&numbers.contains(1)&&numbers.contains(100),"exactly 100 numbered reasoning questions");
 for(int grade=1;grade<=2;grade++){for(String code:codes){JSONArray levels=new JSONArray().put(code);ok(Rules.validate(config(grade,levels),bank)==25,"grade "+grade+" "+code+" selects exactly 25");}ok(Rules.validate(config(grade,new JSONArray(QuestionCatalog.DEFAULT_LEVELS)),bank)==100,"grade "+grade+" all categories selects 100");}
 JSONArray two=new JSONArray().put("easy").put("intermediate");ok(Rules.validate(config(1,two),bank)==50,"multiple difficulties combine without duplicates");try{Rules.validate(config(1,new JSONArray()),bank);throw new AssertionError();}catch(Exception e){ok(true,"no difficulty yields no valid logic-only configuration");}
 try{QuestionCatalog.levels(new JSONArray().put("unknown"));throw new AssertionError();}catch(Exception e){ok(true,"unknown difficulty is rejected");}
 ArrayList<Integer> all=new ArrayList<Integer>();for(int i=0;i<bank.length();i++)if(QuestionCatalog.matches(bank.getJSONObject(i),5,1,topics,QuestionCatalog.levels(null)))all.add(i);int cursor=0;for(int i=1;i<=100;i++){int next=QuestionCatalog.nextLogicIndex(bank,all,cursor);int actual=bank.getJSONObject(next).getInt("logicNumber");if(actual!=i)throw new AssertionError("sequence "+i+" got "+actual);cursor=actual;}ok(cursor==100,"all 100 are served in increasing difficulty and question order");ok(bank.getJSONObject(QuestionCatalog.nextLogicIndex(bank,all,cursor)).getInt("logicNumber")==1,"wraps to first only after full sequence");
 ArrayList<Integer> middle=new ArrayList<Integer>();Set<String> mid=QuestionCatalog.levels(new JSONArray().put("intermediate"));for(int i=0;i<bank.length();i++)if(QuestionCatalog.matches(bank.getJSONObject(i),5,2,topics,mid))middle.add(i);ok(bank.getJSONObject(QuestionCatalog.nextLogicIndex(bank,middle,0)).getInt("logicNumber")==51,"intermediate-only starts at number 51");ok(bank.getJSONObject(QuestionCatalog.nextLogicIndex(bank,middle,75)).getInt("logicNumber")==51,"intermediate-only wraps within selected category");
 System.out.println(count+" checks passed");
 }
}
